{
  "name": "@whomwah/opencode-nelson-muntz",
  "version": "1.2.0",
  "description": "Nelson Muntz iterative development loop plugin for OpenCode",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "types": "./dist/index.d.ts"
    }
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "prepublishOnly": "bun build src/index.ts --outdir dist --target bun && bunx tsc --emitDeclarationOnly"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "nelson-muntz",
    "ai",
    "iterative-development",
    "autonomous-coding"
  ],
  "author": "",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/whomwah/opencode-nelson-muntz.git"
  },
  "bugs": {
    "url": "https://github.com/whomwah/opencode-nelson-muntz/issues"
  },
  "homepage": "https://github.com/whomwah/opencode-nelson-muntz#readme",
  "devDependencies": {
    "@opencode-ai/plugin": "latest",
    "@semantic-release/changelog": "^6.0.3",
    "@semantic-release/git": "^10.0.1",
    "@types/bun": "latest",
    "prettier": "^3.7.4",
    "semantic-release": "^25.0.2",
    "typescript": "^5.0.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=0.1.0"
  }
}
